import { AsyncLocalStorage } from 'async_hooks';
import { SERVER_STRINGS_EN } from './server-strings-en';
import { INTERNAL_API_KEY, serviceUrl } from './service-urls';

/** Languages the apps offer. English is bundled; Swahili and Lingala are AI-translated on the server. */
export type AppLanguage = 'fr' | 'en' | 'sw' | 'ln';
export const APP_LANGUAGES: readonly AppLanguage[] = ['fr', 'en', 'sw', 'ln'];
/** Languages whose dictionary is generated by the server (not bundled). */
export const GENERATED_LANGUAGES: readonly AppLanguage[] = ['sw', 'ln'];

/** Header the mobile app sends with every request (the app's chosen language). */
export const APP_LANGUAGE_HEADER = 'x-app-language';

/** 'en', 'sw', 'ln' (also 'en-GB', 'sw-CD'…); anything else is French. */
export function normalizeAppLanguage(value: unknown): AppLanguage {
  const raw = Array.isArray(value) ? value[0] : value;
  if (typeof raw !== 'string') return 'fr';
  const first = (raw.split(',')[0]?.trim().toLowerCase() ?? '').split('-')[0];
  return first === 'en' || first === 'sw' || first === 'ln' ? first : 'fr';
}

/**
 * Language chosen in the SENGA app (x-app-language). Accept-Language is ignored on purpose:
 * an English browser must not turn the French web portals half English.
 */
export function languageFromHeaders(headers: Record<string, unknown> | undefined): AppLanguage {
  if (!headers) return 'fr';
  return normalizeAppLanguage(headers[APP_LANGUAGE_HEADER]);
}

type Template = { re: RegExp; out: string; order: number[] };
type Store = { exact: Map<string, string>; templates: Template[] };

function escapeRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildStore(entries: Iterable<readonly [string, string]>): Store {
  const exact = new Map<string, string>();
  const templates: Template[] = [];
  for (const [fr, out] of entries) {
    if (!fr || !out) continue;
    if (!/\{\d+\}/.test(fr)) {
      exact.set(fr, out);
      continue;
    }
    const order: number[] = [];
    const pattern = fr
      .split(/(\{\d+\})/)
      .map((part) => {
        const m = /^\{(\d+)\}$/.exec(part);
        if (m) {
          order.push(Number(m[1]));
          return '([\\s\\S]*?)';
        }
        return escapeRe(part);
      })
      .join('');
    templates.push({ re: new RegExp(`^${pattern}$`), out, order });
  }
  // Longest (most specific) templates first.
  templates.sort((a, b) => b.re.source.length - a.re.source.length);
  return { exact, templates };
}

const stores = new Map<AppLanguage, Store>([['en', buildStore(SERVER_STRINGS_EN)]]);

/** Installs (or replaces) the server dictionary of a generated language (FR text → translation). */
export function registerServerDictionary(lang: AppLanguage, entries: Record<string, string>) {
  if (lang === 'fr' || lang === 'en') return;
  stores.set(lang, buildStore(Object.entries(entries)));
}

/** French source texts of the server dictionary (what the server translates for sw / ln). */
export function serverSourceTexts(): string[] {
  return SERVER_STRINGS_EN.map(([fr]) => fr);
}

/**
 * Translates a French text written by the server into the app language.
 * Unknown texts are returned unchanged, so nothing breaks when a translation is missing.
 */
export function translateServerText(text: string, lang: AppLanguage): string {
  if (lang === 'fr' || !text) return text;
  const store = stores.get(lang);
  if (!store) return text;
  const hit = store.exact.get(text);
  if (hit !== undefined) return hit;
  const trimmed = text.trim();
  if (trimmed !== text) {
    const t = store.exact.get(trimmed);
    if (t !== undefined) return text.replace(trimmed, t);
  }
  if (text.length > 2000) return text;
  for (const t of store.templates) {
    const m = t.re.exec(text);
    if (!m) continue;
    const values: Record<number, string> = {};
    t.order.forEach((idx, i) => {
      // A placeholder value may itself be a known text (a status, a label).
      values[idx] = translateServerText(m[i + 1] ?? '', lang);
    });
    return t.out.replace(/\{(\d+)\}/g, (_, n: string) => values[Number(n)] ?? '');
  }
  return text;
}

/** JSON keys whose string values are UI text the server wrote (never ids, codes or user input). */
export const TRANSLATABLE_KEYS = new Set([
  'message',
  'error',
  'statusLabel',
  'label',
  'title',
  'subtitle',
  'body',
  'hint',
  'notice',
  'warning',
  'detail',
  'helperText',
  'typeLabel',
  'kindLabel',
  'categoryLabel',
  'paymentLabel',
  'serviceLabel',
  'stepLabel',
  'reasonLabel',
  'summary',
  'tip',
  'cta',
  'bannerMessage',
  'displayStatus',
  'remainingLabel',
  'reply',
]);

/**
 * Translates a JSON response for a user who chose another language than French:
 * - string values of [TRANSLATABLE_KEYS] (and string arrays under them),
 * - partner content: an object carrying `translations.<lang>` gets those fields.
 */
export function translateResponseBody(value: unknown, lang: AppLanguage, depth = 0): unknown {
  if (lang === 'fr' || depth > 12 || value == null) return value;
  if (Array.isArray(value)) return value.map((v) => translateResponseBody(v, lang, depth + 1));
  if (typeof value !== 'object') return value;
  const obj = value as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v === 'string' && TRANSLATABLE_KEYS.has(k)) out[k] = translateServerText(v, lang);
    else if (Array.isArray(v) && TRANSLATABLE_KEYS.has(k) && v.every((x) => typeof x === 'string'))
      out[k] = (v as string[]).map((x) => translateServerText(x, lang));
    else out[k] = translateResponseBody(v, lang, depth + 1);
  }
  const tr = obj.translations as Record<string, unknown> | undefined;
  const own = tr && typeof tr === 'object' ? (tr[lang] as Record<string, unknown> | undefined) : undefined;
  if (own && typeof own === 'object') {
    for (const [k, v] of Object.entries(own)) {
      if (typeof v === 'string' && v.trim() && typeof obj[k] === 'string') out[k] = v;
    }
  }
  return out;
}

let refreshTimer: NodeJS.Timeout | undefined;

/**
 * Keeps the Swahili / Lingala server dictionaries of this service up to date
 * (fetched from ride-service, which generates them). Safe to call once at startup.
 */
export function startServerDictionaryRefresh(everyMs = 10 * 60_000) {
  if (refreshTimer) return;
  const refresh = async () => {
    for (const lang of GENERATED_LANGUAGES) {
      try {
        const res = await fetch(serviceUrl('ride', `/internal/i18n/${lang}/server`), {
          headers: { 'x-internal-api-key': INTERNAL_API_KEY },
          signal: AbortSignal.timeout(20_000),
        });
        if (!res.ok) continue;
        const data = (await res.json()) as { strings?: Record<string, string> };
        if (data?.strings && typeof data.strings === 'object') registerServerDictionary(lang, data.strings);
      } catch {
        /* keep the previous dictionary */
      }
    }
  };
  setTimeout(() => void refresh(), 15_000).unref?.();
  refreshTimer = setInterval(() => void refresh(), everyMs);
  refreshTimer.unref?.();
}

const requestLanguage = new AsyncLocalStorage<AppLanguage>();

/**
 * Express middleware: remembers the caller's app language for the whole request,
 * so texts built deep in a service (OTP SMS, withdrawal code) can follow it.
 */
export function appLanguageMiddleware(
  req: { headers: Record<string, unknown> },
  _res: unknown,
  next: () => void,
): void {
  requestLanguage.run(languageFromHeaders(req.headers), next);
}

/** Language of the request being handled ('fr' outside a request). */
export function currentRequestLanguage(): AppLanguage {
  return requestLanguage.getStore() ?? 'fr';
}

/** Runs [fn] as if the request language were [lang] (tests, background jobs). */
export function runWithLanguage<T>(lang: AppLanguage, fn: () => T): T {
  return requestLanguage.run(lang, fn);
}
